<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { useAuth } from '../stores/auth';
import { useClub } from '../stores/club';
import { api, clearSession, errorMessage } from '../services/api';
import StateNotice from '../components/StateNotice.vue';
const auth = useAuth(), club = useClub(), router = useRouter(); const sessions = ref<any[]>([]), name = ref(auth.user?.name ?? ''), error = ref(''), message = ref(''), busy = ref(false);
async function load() { try { sessions.value = (await api.get('/auth/sessions')).data; } catch (e) { error.value = errorMessage(e); } }
async function save() { busy.value = true; error.value = ''; try { const { data } = await api.patch('/users/me', { name: name.value }); if (auth.user) auth.user.name = data.name; message.value = 'Perfil actualizado'; } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function revoke(id: string) { try { await api.delete(`/auth/sessions/${id}`); if (id === club.sessionId) { await clearSession(); auth.expired(); await router.replace('/auth/login'); } else await load(); } catch (e) { error.value = errorMessage(e); } }
async function revokeOthers() { try { await api.post('/auth/sessions/revoke-others'); await load(); message.value = 'Las otras sesiones de tu cuenta se han cerrado.'; } catch (e) { error.value = errorMessage(e); } }
async function logout() { busy.value = true; try { await auth.logout(); club.reset(); await router.replace('/auth/login'); } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
onMounted(load);
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">TU ESPACIO</span><h1>El juego empieza <span class="accent">contigo.</span></h1><p>Tu cuenta, tus organizaciones y tus sesiones.</p></div><button class="button subtle" :disabled="busy" @click="logout"><i aria-hidden="true" class="pi pi-sign-out" /> Cerrar sesión</button></div><StateNotice :error="error" @retry="load" /><p v-if="message" class="alert success">{{ message }}</p><div class="dashboard-grid"><section class="panel"><div class="profile-avatar small">{{ auth.user?.name.slice(0, 1) }}</div><h2>{{ auth.user?.name }}</h2><p class="muted">{{ auth.user?.email }}</p><form class="editor-form section-gap" @submit.prevent="save"><label>Nombre<input v-model="name" required minlength="2" maxlength="120" autocomplete="name"></label><button class="button primary" :disabled="busy">Guardar perfil</button></form></section><section class="panel"><span class="eyebrow">MIS ORGANIZACIONES</span><div v-for="m in club.memberships" :key="m.organization.id" class="roster-row"><strong>{{ m.organization.name }}</strong><span class="role-tag">{{ m.role.key }}</span></div><StateNotice :empty="!club.memberships.length" /><RouterLink class="button subtle section-gap" to="/welcome">Crear o unirme a un equipo <i aria-hidden="true" class="pi pi-arrow-right" /></RouterLink></section></div><section class="panel section-gap"><span class="eyebrow">SEGURIDAD</span><div class="section-heading"><h2>Sesiones activas</h2><button class="button subtle" @click="revokeOthers">Cerrar las otras sesiones</button></div><div v-for="s in sessions" :key="s.id" class="session-row"><i aria-hidden="true" class="pi pi-mobile" /><div><strong>{{ s.userAgent?.includes('Android') ? 'Dispositivo Android' : 'Navegador o dispositivo' }}</strong><p>{{ s.activeOrganization?.name ?? 'Sin equipo activo' }} <span v-if="s.id === club.sessionId" class="role-tag">Esta sesión</span></p><p>Inicio: {{ new Date(s.createdAt).toLocaleString('es') }}</p><small class="muted">Caduca: {{ new Date(s.expiresAt).toLocaleDateString('es') }}</small></div><button class="button subtle" @click="revoke(s.id)">Revocar</button></div><p class="chart-footnote">Revocar una sesión impide seguir usando sus tokens, incluido el dispositivo actual.</p></section></section></template>
